	private static FilterPlan directPlan(NativeLmdbQuerySource source, boolean minus, boolean extension,
			boolean nullable, boolean distinct) {
		long yes = id(source, "yes");
		SlotPlan input = new JoinPlan(pattern(source, 0, "anchor", Term.constant(yes), 1D),
				pattern(source, 0, "eligible", Term.constant(yes), 1D));
		PatternPlan seed = pattern(source, 1, "seed", Term.constant(yes), 1D);
		PatternPlan candidate = pattern(source, 1, "candidate", Term.slot(2), 2D);
		SlotPlan assured = new JoinPlan(seed, candidate);
		SlotPlan local = new UnionPlan(assured,
				nullable ? seed
						: new JoinPlan(pattern(source, 1, "seed", Term.constant(yes), 1D),
								pattern(source, 1, "candidate", Term.slot(2), 2D)));
		SlotPlan body = new JoinPlan(local, pattern(source, 2, "witness", Term.constant(yes), 1D));
		if (distinct) {
			// Zero-or-one path compilation can introduce this native producer inside a witness.
			body = new RowDistinctPlan(body, new int[] { 1, 2 });
		}
		SlotPlan wrapped = minus
				? new MinusPlan(body, pattern(source, 1, "candidate", Term.constant(yes), 1D), 1L << 1)
				: new LeftJoinPlan(body, pattern(source, 1, "seed", Term.constant(yes), 1D));
		if (extension) {
			wrapped = new ExtensionPlan(wrapped, new CopyBinding[] { CopyBinding.constant(3, yes) });
		}
		return new FilterPlan(input, new ExistsFilter(wrapped), 0L);
	}

	private static PatternPlan pattern(NativeLmdbQuerySource source, int subject, String predicate,
			Term object, double rows) {
		return new PatternPlan(Term.slot(subject), Term.constant(id(source, predicate)), object, Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, rows, source.indexAccessProfile());
	}

	private static long id(NativeLmdbQuerySource source, String local) {
		return source.idOf(org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance().createIRI(NS + local));
	}

	private static List<String> directRows(SyntheticValueSource source, NativeSlotLayout layout, SlotPlan input,
			String forcing, Boolean nativeWitness, List<String> expected) throws Exception {
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		when(strategy.forcedExecutionStrategyName()).thenReturn(forcing);
		NativeRowsStep step = new NativeRowsStep(source, input, layout, new int[] { 0 },
				new String[] { "row" }, false, new int[0], new boolean[0], 0L, -1L, false,
				strategy, null, null, Set.of(), null, null);
		List<String> result = new ArrayList<>();
		List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
		try (AutoCloseable ignored = LmdbNativeDecisionTestAccess.captureSelections(selected);
				NativeRowsIteration rows = new NativeRowsIteration(step, source, EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				result.add(rows.next().getValue("row").stringValue());
			}
		}
		assertThat(selected).singleElement().satisfies(selection -> assertThat(selection.id()).isEqualTo(forcing));
		List<String> sorted = result.stream().sorted().toList();
		assertThat(sorted).as("exact physical route and complete answer bag precede quote assertions")
				.isEqualTo(expected);
		if (nativeWitness != null) {
			LmdbNativeDecisionTestAccess.Selected selection = selected.getFirst();
			assertThat(selection.quote()).isNotNull();
			assertThat(selection.quote().expectedFeatures()).isNotNull();
			double membership = selection.quote().expectedFeatures()[LmdbNativeCostVector.Feature.MEMBERSHIP_TEST
					.ordinal()];
			System.out.println(
					"opened native witness=" + nativeWitness + " route=" + forcing + " membership=" + membership);
			if (nativeWitness) {
				assertThat(membership).as("the exact native EXISTS hook performs its own memo membership work")
						.isPositive();
			} else {
				assertThat(membership).as("the assured control retains direct IR witness access without a native memo")
						.isZero();
			}
		}
		return sorted;
	}

	private static List<String> rows(SailRepository repository, String sparql) {
		List<String> result = new ArrayList<>();
		try (var connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(sparql);
			try (var rows = query.evaluate()) {
				while (rows.hasNext()) {
					result.add(rows.next().getValue("row").stringValue());
				}
			}
		}
		return result.stream().sorted().toList();
	}
